// Builds worker/dist/index.bundle.js — a single-file version of index.js with
// pricing.js inlined, for pasting into the Cloudflare dashboard's "Edit code"
// editor (which only accepts one file). The two-file source (index.js +
// pricing.js) stays the real source of truth in git; this is a build output,
// regenerated by running: node worker/build-bundle.mjs
//
// Mechanical, not a general bundler: pricing.js has no imports of its own,
// so this just strips its `export` keywords and prepends it to index.js with
// the `import ... from "./pricing.js"` line removed. Re-run after any change
// to either file, then paste worker/dist/index.bundle.js into the dashboard.

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const dir = path.dirname(fileURLToPath(import.meta.url));
const pricingSrc = fs.readFileSync(path.join(dir, "pricing.js"), "utf8");
const indexSrc = fs.readFileSync(path.join(dir, "index.js"), "utf8");

const importLineRe = /^import \{[^}]*\} from "\.\/pricing\.js";\n/m;
if (!importLineRe.test(indexSrc)) {
  throw new Error("Could not find the pricing.js import line in index.js — bundler is out of sync, fix by hand.");
}

const inlinedPricing = pricingSrc
  .replace(/^export function /gm, "function ")
  .replace(/^export const /gm, "const ")
  .replace(/^export let /gm, "let ");

if (/^export /m.test(inlinedPricing)) {
  const stray = inlinedPricing.match(/^export .*/m)[0];
  throw new Error("pricing.js has an export form the bundler doesn't handle: " + stray);
}

const bundled = indexSrc.replace(
  importLineRe,
  "// ---- inlined from worker/pricing.js by build-bundle.mjs — do not edit below by hand ----\n" +
    inlinedPricing +
    "\n// ---- end inlined pricing.js ----\n\n"
);

const outDir = path.join(dir, "dist");
fs.mkdirSync(outDir, { recursive: true });
const outPath = path.join(outDir, "index.bundle.js");
fs.writeFileSync(outPath, bundled);
console.log("Wrote " + outPath + " (" + bundled.split("\n").length + " lines)");
